// chat — the TS face of rust.rs. Not server actions: IPC to the local Rust plugin.
import { Channel, invoke, isTauri } from "@tauri-apps/api/core"

import type { DriverKind, Event } from "../driver/types"
import type { RepoEntry } from "./types"

export interface AskOptions {
  /** Generated by the caller so `stop` can name the job before `ask` resolves. */
  jobId: string
  session?: string | null
  driver?: DriverKind
  /** The web seat when `driver` is `web` (`chatgpt`, `deepseek`, `glm`, `gemini`); the run asks that site's page. */
  seat?: string
  /** A started task (`databayt/<repo>#<n>`): its repos open with the run and the prompt points at TASK.md. */
  taskId?: string | null
  /** Limits the run to one repository of the department (null: all repos). */
  repo?: string | null
  /** Claude's permission mode: "plan" answers with a plan first. Anything else runs as auto. */
  mode?: "plan" | "auto" | null
  /** One of the department pack's route ids (`PackInfo.routes`): permission mode, model, effort, agent and suffix. Wins over `mode`. */
  route?: string | null
  /**
   * A model for this run only (`opus` | `sonnet` | `haiku`): the formula's own. Settings → Model may pin it
   * over this in Rust (a fixed policy wins); there is no per-run picker in the chat.
   */
  model?: string | null
  /** An effort for this run only (a formula's), same plumbing as `model`. */
  effort?: string | null
  /**
   * What the UI knew before Rust did, for the `run` line of `station-log.jsonl`: the formula it filled, when it was
   * tapped and when Send was pressed (ms since the epoch). Rust adds spawn, first event and done.
   */
  timing?: { formula?: string | null; tTap?: number | null; tSend?: number | null } | null
  /** The chat's title in Sessions (a composed request is titled by its sentence, not by the long prompt). */
  title?: string | null
}

/** Runs one prompt, calling `onEvent` for every streamed event. Resolves when the run ends. */
export async function ask(
  prompt: string,
  { jobId, session = null, driver, seat, taskId = null, repo = null, mode = null, route = null, model = null, effort = null, timing = null, title = null }: AskOptions,
  onEvent: (event: Event) => void
): Promise<void> {
  if (!isTauri()) throw new Error("not in the machine app")
  const channel = new Channel<Event>()
  channel.onmessage = onEvent
  await invoke("plugin:chat|ask", { prompt, session, driver: driver ?? null, seat: seat ?? null, jobId, taskId, repo, mode, route, model, effort, timing, title, channel })
}

/**
 * Rewrites rough text as one professional brief for the department. When the pack has routes the
 * answer ends with a `route: <id>` line. One fresh sonnet turn that reads the department's context first (240 s at most); nothing is kept.
 */
export async function refine(prompt: string, repo: string | null): Promise<string> {
  if (!isTauri()) throw new Error("not in the machine app")
  return invoke<string>("plugin:chat|refine", { prompt, repo })
}

/** Cancels a running job. False when it was not running. */
export async function stop(jobId: string): Promise<boolean> {
  if (!isTauri()) return false
  return invoke<boolean>("plugin:chat|stop", { jobId })
}

/** The repositories the menu offers for a department on this machine, hogwarts first; empty outside the app. */
export async function repoMenu(department: string): Promise<RepoEntry[]> {
  if (!isTauri()) return []
  return invoke<RepoEntry[]>("plugin:chat|repo_menu", { department })
}
